{
  "category_edits": [
    {
      "category": "sequence_modeling",
      "rationale": "Reduce context to max(2, floor(0.75 * L)) across all four datasets to reduce distant-history noise and attention cost. Training and validation use MAXLEN; checkpoint metadata passes the same length to the generated predictor. Preserve chronological order, recency-aligned positions, and all other model and training settings.",
      "edits": [
        {
          "find": "MAXLEN       = int(os.environ.get(\"SASREC_MAXLEN\",    \"128\"))",
          "replace": "MAXLEN       = max(2, (3 * int(os.environ.get(\"SASREC_MAXLEN\", \"128\"))) // 4)"
        }
      ]
    }
  ],
  "change_summary": "Shorten the default context from 128 to 96 interactions, consistently across training, validation, model construction, and generated inference."
}
